359	import java.math.BigDecimal;
360	import java.math.RoundingMode;
361	import java.time.LocalDate;
362	import java.util.List;
363	import net.officefloor.hq.app.Audit;
364	import net.officefloor.hq.app.person.Person;
365	import net.officefloor.hq.app.person.PersonRepository;
366	import net.officefloor.hq.app.rate.Rate;
367	import net.officefloor.hq.app.rate.RateRepository;
368	import net.officefloor.hq.app.sheet.SheetService;
369	import org.springframework.http.HttpStatus;
370	import org.springframework.stereotype.Service;
371	import org.springframework.transaction.annotation.Transactional;
372	import org.springframework.web.server.ResponseStatusException;
373	
374	/** The claims people make on a sheet. */
375	@Service
376	public class ClaimService {
377	
378	    private final ClaimRepository claims;
379	    private final PersonRepository people;
380	    private final RateRepository rates;
381	    private final SheetService sheets;
382	    private final Audit audit;
383	
384	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates,
385	            SheetService sheets, Audit audit) {
386	        this.claims = claims;
387	        this.people = people;
388	        this.rates = rates;
389	        this.sheets = sheets;
390	        this.audit = audit;
391	    }
392	
393	    /** The claims on the sheet, newest first. */
394	    @Transactional(readOnly = true)
395	    public List<Claim> list(String sheetId) {
396	        return claims.findBySheetIdOrderByIdDesc(sheetId);
397	    }
398	
399	    /** Add a claim for a person; a date left out takes the sheet's today. */
400	    @Transactional
401	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
402	        Person person = person(sheetId, personId);
403	        LocalDate on = date != null ? date : sheets.today(sheetId);
404	        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, amount, on, note));
405	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, claim));
406	        return claim;
407	    }
408	
409	    /** Change a claim's amount, date and note; a date left out takes the sheet's today. */
410	    @Transactional
411	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
412	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
413	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
414	        claim.setAmount(amount);
415	        claim.setDate(date != null ? date : sheets.today(sheetId));
416	        claim.setNote(note);
417	        Claim saved = claims.saveAndFlush(claim);
418	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
419	        return saved;
420	    }
421	
422	    /** Move a claim to a new status; a change its current status does not allow is refused, and so
423	     *  is settling a claim by the user who opened it. */
424	    @Transactional
425	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
426	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId)
427	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
428	        if (!claim.getStatus().canBecome(to)) {
429	            throw new ResponseStatusException(HttpStatus.CONFLICT,
430	                    "A " + claim.getStatus() + " claim cannot become " + to);
431	        }
432	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
433	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
434	                    "The user who opened a claim cannot settle it");
435	        }
436	        // The number recorded for a void claim is the one it had.
437	        Integer number = claim.getNumber();
438	        claim.setStatus(to);
439	        if (to == ClaimStatus.OPEN) {
440	            claim.setNumber(sheets.nextClaimNumber(sheetId));
441	            claim.setOpenedBy(user);
442	        } else if (to == ClaimStatus.VOID) {
443	            claim.setNumber(null);
444	        }
445	        Person person = person(sheetId, claim.getPersonId());
446	        if (to == ClaimStatus.SETTLED) {
447	            // Settling fixes the due at what it is now (the figure a statement bound it to, if any);
448	            // later changes to rates do not alter it.
449	            claim.setSettledDue(figure(sheetId, person, claim));
450	        }
451	        Claim saved = claims.saveAndFlush(claim);
452	        String event = switch (to) {
453	            case OPEN -> "CLAIM_OPENED";
454	            case SETTLED -> "CLAIM_SETTLED";
455	            case VOID -> "CLAIM_VOIDED";
456	            case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
457	        };
458	        String line = record(event, sheetId, user, person, saved, to == ClaimStatus.VOID ? number : saved.getNumber());
459	        if (to == ClaimStatus.SETTLED) {
460	            line += " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString());
461	        }
462	        audit.recordOnCommit(line);
463	        return saved;
464	    }
465	
466	    /** The due figure a claim shows and totals: the one fixed when it was settled, or else the one
467	     *  its person's last statement bound it to, or else its live due; null when there is none. */
468	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
469	        if (claim.getSettledDue() != null) {
470	            return claim.getSettledDue();
471	        }
472	        if (claim.isStated() && claim.getStatedDue() != null) {
473	            return claim.getStatedDue();
474	        }
475	        return due(sheetId, person, claim);
476	    }
477	
478	    /** A person's due-total: the sum of the figures of their claims that count; null (n/a) when
479	     *  their grade has no rate on the sheet's today and no counting claim keeps a fixed figure. */
480	    public BigDecimal dueTotal(String sheetId, Person person, List<Claim> theirs) {
481	        List<Claim> counted = theirs.stream().filter(c -> c.getStatus().counts()).toList();
482	        boolean rated = rates.findInForce(sheetId, person.getGrade(), sheets.today(sheetId)).isPresent();
483	        boolean fixed = counted.stream().anyMatch(c -> c.getSettledDue() != null
484	                || (c.isStated() && c.getStatedDue() != null));
485	        if (!rated && !fixed) {
486	            return null;
487	        }
488	        return counted.stream().map(c -> figure(sheetId, person, c)).filter(d -> d != null)
489	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
490	    }
491	
492	    /** A claim's due at the rate for the person's grade in force on the claim's date: amount times
493	     *  pct divided by 100, rounded half to even to two decimals; null when no rate applies on that date. */
494	    private BigDecimal due(String sheetId, Person person, Claim claim) {
495	        return rates.findInForce(sheetId, person.getGrade(), claim.getDate())
496	                .map(Rate::getPct)
497	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
498	                .orElse(null);
499	    }
500	
501	    private Person person(String sheetId, long personId) {
502	        return people.findByIdAndSheetId(personId, sheetId)
503	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
504	    }
505	
506	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
507	        return record(event, sheetId, user, person, claim, claim.getNumber());
508	    }
509	
510	    /** An audit record about a claim; one that has a number carries it at the end. */
511	    private static String record(String event, String sheetId, String user, Person person, Claim claim,
512	            Integer number) {
513	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
514	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
515	                + (number != null ? " number=" + number : "");
516	    }
517	}
