519	
520	/** Where a claim is in its life: it starts as a draft, is opened and then settled; a draft or an
521	 *  open claim may be voided. A settled or voided claim cannot change status. */
522	public enum ClaimStatus {
523	    DRAFT, OPEN, SETTLED, VOID;
524	
525	    /** Whether a claim at this status may move to {@code to}. */
526	    public boolean canBecome(ClaimStatus to) {
527	        return switch (to) {
528	            case OPEN -> this == DRAFT;
529	            case SETTLED -> this == OPEN;
530	            case VOID -> this == DRAFT || this == OPEN;
531	            case DRAFT -> false;
532	        };
533	    }
534	
535	    /** Whether a claim at this status counts toward what its person has claimed. */
536	    public boolean counts() {
537	        return this == OPEN || this == SETTLED;
538	    }
539	}
