774	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
775	        if (person.getVersion() != version) {
776	            throw changedMeanwhile();
777	        }
778	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, name, personId)) {
779	            throw nameInUse();
780	        }
781	        person.setName(name);
782	        person.setGrade(grade);
783	        Person saved = saveUnique(person);
784	        audit.recordOnCommit(record("PERSON_EDITED", sheetId, user, saved));
785	        return saved;
786	    }
787	
788	    private static String record(String event, String sheetId, String user, Person person) {
789	        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade=" + person.getGrade();
790	    }
791	
792	    /** Save, refusing a name another user took on the sheet in the meantime, or a person another
793	     *  user saved in the meantime. */
794	    private Person saveUnique(Person person) {
795	        try {
796	            return people.saveAndFlush(person);
797	        } catch (DataIntegrityViolationException e) {
798	            throw nameInUse();
799	        } catch (OptimisticLockingFailureException e) {
800	            throw changedMeanwhile();
801	        }
802	    }
803	
804	    private static ResponseStatusException changedMeanwhile() {
805	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
806	                "Someone else saved this person in the meantime");
807	    }
808	
809	    private static ResponseStatusException nameInUse() {
810	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet");
811	    }
812	}
